function addFromShelf(type,at=null){if(!canAdd(type))return false;framing='manual';save();const p=make(type);if(at)Object.assign(p,normalized(at.x-(meter(p)?120:80),at.y-50));else{const box=cameraBox();Object.assign(p,normalized(view.x+box.w*.45-80,view.y+box.h*.45-50))}p.user=true;clampPart(p);if(!at)placeVacant(p);revealPart(p);selected=p.id;scene='custom';render();controls();toast('拖曳元件移動；點接柱接線');return true}
document.querySelectorAll('[data-add]').forEach(button=>{button.onpointerdown=e=>{if(!canAdd(button.dataset.add)){e.preventDefault();return}toolDrag={type:button.dataset.add,x:e.clientX,y:e.clientY,moved:false};button.setPointerCapture(e.pointerId)};button.onpointermove=e=>{if(toolDrag&&Math.hypot(e.clientX-toolDrag.x,e.clientY-toolDrag.y)>8)toolDrag.moved=true};button.onpointerup=e=>{if(!toolDrag)return;const d=toolDrag;toolDrag=null;if(!canAdd(d.type))return;if(d.moved){const r=geometry();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)return;addFromShelf(d.type,scenePoint(e))}else addFromShelf(d.type)};button.onpointercancel=()=>toolDrag=null;button.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();addFromShelf(button.dataset.add)}}});

document.querySelectorAll('[data-scene]').forEach(b=>b.onclick=()=>preset(b.dataset.scene));$('undo').onclick=undo;$('cancelWire').onclick=()=>{pending=null;render()};$('clear').onclick=()=>{resetFaultTransient();save();parts=[];wires=[];selected=null;pending=null;scene='custom';render();controls()};$('fit').onclick=()=>fitCircuit();$('workspace').onclick=()=>fitCircuit(true);$('zoomIn').onclick=()=>zoomAt(1.35);$('zoomOut').onclick=()=>zoomAt(1/1.35);$('play').onclick=()=>{playing=!playing;$('play').textContent=playing?'Ⅱ 暫停':'▶ 播放';$('play').setAttribute('aria-pressed',String(!playing))};$('slow').onclick=()=>{slow=!slow;$('slow').setAttribute('aria-pressed',String(slow))};document.querySelectorAll('[data-flow-mode]').forEach(b=>b.onclick=()=>{electron=b.dataset.flowMode==='electron';buildParticles()});$('numbers').onchange=()=>render();document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!document.fullscreenElement){pending=null;cutting=false;render()}if((e.ctrlKey||e.metaKey)&&e.key==='z'&&e.target.tagName!=='INPUT'){e.preventDefault();undo()}});
// A redraw can move a new button under a touch that began on SVG. Ignore its
// compatibility click; a deliberate button tap has its own outside pointerdown.
document.addEventListener('pointerdown',e=>{const onStage=$('stage').contains(e.target);pointerOrigins.set(e.pointerId,onStage?'stage':'outside');if(!onStage){stageClickGuard=null;pointers.delete(e.pointerId);if($('stage').hasPointerCapture(e.pointerId))$('stage').releasePointerCapture(e.pointerId)}},true);
document.addEventListener('click',e=>{if(stageClickGuard&&e.detail>0&&(e.pointerId===undefined||e.pointerId===stageClickGuard.pointerId)&&performance.now()-stageClickGuard.time<800&&Math.hypot(e.clientX-stageClickGuard.x,e.clientY-stageClickGuard.y)<6){e.preventDefault();e.stopImmediatePropagation();stageClickGuard=null}},true);
// Touch controls complete from a deliberate down/up on the same button. Some
// mobile engines suppress the compatibility click after a captured SVG drag.
const touchButtons=new Map(),completedButtonTouches=new Map();
document.addEventListener('pointerdown',e=>{if(e.pointerType!=='touch')return;const button=e.target.closest?.('button');if(button&&!button.disabled&&!button.dataset.add)touchButtons.set(e.pointerId,{button,x:e.clientX,y:e.clientY});for(const [id,done]of completedButtonTouches)if(performance.now()-done.time>1200)completedButtonTouches.delete(id)},true);
document.addEventListener('pointerup',e=>{const start=touchButtons.get(e.pointerId);touchButtons.delete(e.pointerId);if(!start||!start.button.isConnected||start.button.disabled||Math.hypot(e.clientX-start.x,e.clientY-start.y)>9)return;const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('button');if(target!==start.button)return;e.preventDefault();completedButtonTouches.set(e.pointerId,{x:e.clientX,y:e.clientY,time:performance.now()});start.button.click()},true);
document.addEventListener('pointercancel',e=>touchButtons.delete(e.pointerId),true);
document.addEventListener('click',e=>{if(e.detail===0)return;const done=completedButtonTouches.get(e.pointerId);if(done&&performance.now()-done.time<1000&&Math.hypot(e.clientX-done.x,e.clientY-done.y)<8){e.preventDefault();e.stopImmediatePropagation()}},true);
$('disconnectWire').onclick=disconnectSelected;
document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)||e.target.isContentEditable||e.ctrlKey||e.metaKey)return;if(e.key.toLowerCase()==='r'&&selected&&!selected.startsWith('w')){e.preventDefault();rotatePart(selected)}if(['Delete','Backspace'].includes(e.key)&&selected?.startsWith('w')){e.preventDefault();disconnectSelected()}});
