let resizePending=false;new ResizeObserver(()=>{if(resizePending)return;resizePending=true;requestAnimationFrame(()=>{resizePending=false;render();if(framing==='circuit')fitCircuit();else if(framing==='workspace')fitCircuit(true);else{const p=parts.find(p=>p.id===selected);if(resizeSelectedWasVisible&&meter(p)){revealPart(p);applyView()}}resizeSelectedWasVisible=false})}).observe($('viewport'));

function syncFullscreen(){const active=Boolean(document.fullscreenElement);$('fullscreen').textContent=active?'⛶ 退出全螢幕':'⛶ 全螢幕';$('fullscreen').setAttribute('aria-pressed',String(active));requestAnimationFrame(()=>render())}
function fullscreenFeedback(message){toast(message);$('fullscreenStatus').hidden=false;$('fullscreenStatus').textContent=message}
$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement){await document.exitFullscreen();return}if(!document.documentElement.requestFullscreen){fullscreenFeedback('此瀏覽器不支援程式全螢幕；可用瀏覽器選單放大，並橫放裝置。');return}await document.documentElement.requestFullscreen();$('fullscreenStatus').hidden=true;try{const lock=screen.orientation?.lock?.('landscape');if(lock?.catch)lock.catch(()=>{})}catch{}}catch{fullscreenFeedback('無法切換全螢幕；可使用瀏覽器選單，或再次按此按鈕重試。')}finally{syncFullscreen()}};
document.addEventListener('fullscreenchange',()=>{if(!document.fullscreenElement){try{screen.orientation?.unlock?.()}catch{}}syncFullscreen()});document.addEventListener('fullscreenerror',()=>{fullscreenFeedback('瀏覽器未允許全螢幕；可使用瀏覽器選單或重試。');syncFullscreen()});$('dismissOrientation').onclick=()=>$('orientationHint').hidden=true;$('toggleControls').onclick=()=>{const collapsed=document.querySelector('.app').classList.toggle('tools-collapsed');$('controls').hidden=collapsed;$('toggleControls').setAttribute('aria-expanded',String(!collapsed));$('toggleControls').textContent=collapsed?'展開工具':'收合工具'};

preset('simple',false);history=[];$('undo').disabled=true;requestAnimationFrame(animate);document.fonts.ready.then(()=>requestAnimationFrame(()=>{if(framing==='circuit'&&!drag&&!pending){if(!history.length&&scene!=='custom')centerPresetInWorld();fitCircuit()}}));

